std::optional<std::size_t> rvaoff(const PeInfo&pe,std::uint32_t rva,std::size_t n){if(rva<pe.headers_size&&rva<n)return std::size_t(rva);for(const auto&s:pe.sections){auto span=std::max(s.vsize,s.raw_size);if(rva>=s.rva&&std::uint64_t(rva)<std::uint64_t(s.rva)+span){auto delta=std::uint64_t(rva)-s.rva;if(delta>=s.raw_size)return{};auto o=std::uint64_t(s.raw_offset)+delta;if(o<n)return std::size_t(o);}}return{};}
ZydisRegister large(ZydisRegister r){return r==ZYDIS_REGISTER_NONE?r:ZydisRegisterGetLargestEnclosing(ZYDIS_MACHINE_MODE_LONG_64,r);}
struct Decoded{std::uint32_t rva=0;ZydisDecodedInstruction zi{};std::array<ZydisDecodedOperand,ZYDIS_MAX_OPERAND_COUNT>ops{};};
std::span<const std::uint8_t> raw_function(std::span<const std::uint8_t>d,const PeInfo&pe,const PeRuntimeFunction&rf){if(rf.end_rva<=rf.begin_rva)return{};auto b=rvaoff(pe,rf.begin_rva,d.size()),e=rvaoff(pe,rf.end_rva-1,d.size());if(!b||!e||*e<*b||*e-*b+1!=rf.end_rva-rf.begin_rva)return{};return d.subspan(*b,*e-*b+1);}
bool has_prerequisite_raw(std::span<const std::uint8_t>s){std::size_t timing=0,pos=0;while(pos<s.size()){auto*p=static_cast<const std::uint8_t*>(std::memchr(s.data()+pos,0x0f,s.size()-pos));if(!p)break;const auto i=static_cast<std::size_t>(p-s.data());if(i+1<s.size()&&s[i+1]==0xa2)return true;if(i+2<s.size()&&s[i+1]==0x01&&s[i+2]==0xd0)return true;if(i+1<s.size()&&s[i+1]==0x31){if(++timing>=2)return true;}else if(i+2<s.size()&&s[i+1]==0x01&&s[i+2]==0xf9){if(++timing>=2)return true;}pos=i+1;}return false;}
std::vector<Decoded> decode(std::span<const std::uint8_t>d,const PeInfo&pe,const PeRuntimeFunction&rf){std::vector<Decoded>out;if(rf.end_rva<=rf.begin_rva)return out;ZydisDecoder dec;if(!ZYAN_SUCCESS(ZydisDecoderInit(&dec,ZYDIS_MACHINE_MODE_LONG_64,ZYDIS_STACK_WIDTH_64)))return out;auto cur=rf.begin_rva;while(cur<rf.end_rva&&out.size()<4096){auto o=rvaoff(pe,cur,d.size());if(!o||*o>=d.size())break;Decoded x;x.rva=cur;auto avail=std::min<std::size_t>(d.size()-*o,rf.end_rva-cur);if(!ZYAN_SUCCESS(ZydisDecoderDecodeFull(&dec,d.data()+*o,avail,&x.zi,x.ops.data()))||!x.zi.length)break;out.push_back(x);cur+=x.zi.length;}return out;}
std::string hx(std::uint64_t v){std::ostringstream o;o<<"0x"<<std::hex<<v;return o.str();}
std::string regname(ZydisRegister r){auto*s=ZydisRegisterGetString(r);return s?s:"UNKNOWN";}
std::string mnem(ZydisMnemonic m){auto*s=ZydisMnemonicGetString(m);std::string out=s?s:"UNKNOWN";std::transform(out.begin(),out.end(),out.begin(),[](unsigned char c){return static_cast<char>(std::toupper(c));});return out;}
struct Taint{std::string output;std::uint32_t width=32;bool inverted=false;bool via_stack=false;std::uint32_t spill_rva=0,reload_rva=0;std::string stack_slot;Taint()=default;Taint(std::string o,std::uint32_t w=32,bool inv=false):output(std::move(o)),width(w),inverted(inv){}};
struct Cond{bool valid=false;std::string output,shape;std::uint64_t mask=0,imm=0;std::uint32_t rva=0,width=32;int ttl=0;bool inverted=false;bool via_stack=false;std::uint32_t spill_rva=0,reload_rva=0;std::string stack_slot;Cond()=default;Cond(bool v,std::string o,std::string sh,std::uint64_t ma,std::uint64_t im,std::uint32_t rv,std::uint32_t w,int t,bool inv):valid(v),output(std::move(o)),shape(std::move(sh)),mask(ma),imm(im),rva(rv),width(w),ttl(t),inverted(inv){}};
void inherit_stack(Cond&c,const Taint&t){c.via_stack=t.via_stack;c.spill_rva=t.spill_rva;c.reload_rva=t.reload_rva;c.stack_slot=t.stack_slot;}
enum class StackBase:std::uint8_t{RSP,RBP};
struct StackSlot{StackBase base=StackBase::RSP;std::int64_t offset=0;std::uint16_t width=0;bool operator<(const StackSlot&o)const{return std::tie(base,offset,width)<std::tie(o.base,o.offset,o.width);}};
struct LocalStackTaint{bool valid=true;std::int64_t rsp_delta=0;std::map<StackSlot,Taint>slots;};
bool add_i64(std::int64_t&a,std::int64_t b){if(b>0&&a>std::numeric_limits<std::int64_t>::max()-b)return false;if(b<0&&a<std::numeric_limits<std::int64_t>::min()-b)return false;a+=b;return true;}
std::string stack_slot_name(const StackSlot&s){std::ostringstream o;o<<(s.base==StackBase::RSP?"RSP":"RBP");if(s.offset>=0)o<<"+0x"<<std::hex<<static_cast<std::uint64_t>(s.offset);else o<<"-0x"<<std::hex<<(static_cast<std::uint64_t>(-(s.offset+1))+1);o<<"/"<<std::dec<<s.width;return o.str();}
std::optional<StackSlot> fixed_stack_slot(const ZydisDecodedOperand&o,const LocalStackTaint&st){if(!st.valid||o.type!=ZYDIS_OPERAND_TYPE_MEMORY||o.mem.index!=ZYDIS_REGISTER_NONE||!o.size||o.size>64)return{};auto b=large(o.mem.base);if(b!=ZYDIS_REGISTER_RSP&&b!=ZYDIS_REGISTER_RBP)return{};std::int64_t off=o.mem.disp.has_displacement?o.mem.disp.value:0;if(b==ZYDIS_REGISTER_RSP&&!add_i64(off,st.rsp_delta))return{};return StackSlot{b==ZYDIS_REGISTER_RSP?StackBase::RSP:StackBase::RBP,off,static_cast<std::uint16_t>(o.size)};}
bool overlaps(const StackSlot&a,const StackSlot&b){if(a.base!=b.base)return false;const auto ab=(a.width+7)/8,bb=(b.width+7)/8;if(!ab||!bb)return true;return a.offset<b.offset+static_cast<std::int64_t>(bb)&&b.offset<a.offset+static_cast<std::int64_t>(ab);}
void erase_stack_provenance(std::map<ZydisRegister,Taint>&taint,LocalStackTaint&st){st.slots.clear();for(auto it=taint.begin();it!=taint.end();){if(it->second.via_stack)it=taint.erase(it);else ++it;}}
bool explicit_rsp_adjust(const Decoded&x,LocalStackTaint&st){if(!x.zi.operand_count_visible||x.ops[0].type!=ZYDIS_OPERAND_TYPE_REGISTER||large(x.ops[0].reg.value)!=ZYDIS_REGISTER_RSP||(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)==0)return false;if((x.zi.mnemonic==ZYDIS_MNEMONIC_ADD||x.zi.mnemonic==ZYDIS_MNEMONIC_SUB)&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_IMMEDIATE&&!x.ops[1].imm.is_relative){auto v=x.ops[1].imm.value.s;if(x.zi.mnemonic==ZYDIS_MNEMONIC_SUB){if(v==std::numeric_limits<std::int64_t>::min())return false;v=-v;}return add_i64(st.rsp_delta,v);}if(x.zi.mnemonic==ZYDIS_MNEMONIC_LEA&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_MEMORY&&x.ops[1].mem.index==ZYDIS_REGISTER_NONE&&large(x.ops[1].mem.base)==ZYDIS_REGISTER_RSP){auto v=x.ops[1].mem.disp.has_displacement?x.ops[1].mem.disp.value:0;return add_i64(st.rsp_delta,v);}return false;}
void advance_taint(const Decoded&x,std::map<ZydisRegister,Taint>&taint,LocalStackTaint&st){
    if(x.zi.meta.category==ZYDIS_CATEGORY_CALL){taint.clear();st.slots.clear();st.valid=false;return;}
    if(x.zi.meta.category==ZYDIS_CATEGORY_COND_BR||x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR){erase_stack_provenance(taint,st);st.valid=false;return;}
    bool rsp_written=false,rbp_written=false;
    for(std::uint8_t i=0;i<x.zi.operand_count_visible;++i){const auto&o=x.ops[i];if(o.type!=ZYDIS_OPERAND_TYPE_REGISTER||(o.actions&ZYDIS_OPERAND_ACTION_WRITE)==0)continue;auto r=large(o.reg.value);rsp_written|=r==ZYDIS_REGISTER_RSP;rbp_written|=r==ZYDIS_REGISTER_RBP;}
    if(rsp_written&&!explicit_rsp_adjust(x,st)){erase_stack_provenance(taint,st);st.valid=false;}
    if(rbp_written){erase_stack_provenance(taint,st);st.valid=false;}
    if(st.valid){
        for(std::uint8_t i=0;i<x.zi.operand_count_visible;++i){const auto&o=x.ops[i];if(o.type!=ZYDIS_OPERAND_TYPE_MEMORY||(o.actions&ZYDIS_OPERAND_ACTION_WRITE)==0)continue;auto slot=fixed_stack_slot(o,st);if(slot){for(auto it=st.slots.begin();it!=st.slots.end();){if(overlaps(it->first,*slot))it=st.slots.erase(it);else ++it;}if(i==0&&x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER){auto t=taint.find(large(x.ops[1].reg.value));if(t!=taint.end()){auto q=t->second;q.via_stack=false;q.spill_rva=x.rva;q.reload_rva=0;q.stack_slot=stack_slot_name(*slot);st.slots[*slot]=std::move(q);}}}else{auto b=large(o.mem.base);if(b!=ZYDIS_REGISTER_RIP&&b!=ZYDIS_REGISTER_NONE)st.slots.clear();}}
    }
    if(x.zi.operand_count_visible&&x.ops[0].type==ZYDIS_OPERAND_TYPE_REGISTER&&(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)){auto dst=large(x.ops[0].reg.value);std::optional<Taint>next;if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2){if(x.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER){auto it=taint.find(large(x.ops[1].reg.value));if(it!=taint.end())next=it->second;}else if(x.ops[1].type==ZYDIS_OPERAND_TYPE_MEMORY){if(auto slot=fixed_stack_slot(x.ops[1],st)){auto it=st.slots.find(*slot);if(it!=st.slots.end()){next=it->second;next->via_stack=true;next->reload_rva=x.rva;}}}}else if(x.zi.mnemonic==ZYDIS_MNEMONIC_NOT){auto it=taint.find(dst);if(it!=taint.end()){next=it->second;next->inverted=!next->inverted;}}if(next)taint[dst]=*next;else if(x.zi.mnemonic!=ZYDIS_MNEMONIC_AND)taint.erase(dst);}
}
bool writes_reg(const Decoded&x,ZydisRegister r){r=large(r);for(std::uint8_t i=0;i<x.zi.operand_count_visible;++i){const auto&o=x.ops[i];if(o.type==ZYDIS_OPERAND_TYPE_REGISTER&&(o.actions&ZYDIS_OPERAND_ACTION_WRITE)&&large(o.reg.value)==r)return true;}return false;}
std::optional<std::uint64_t> scalar_before(const std::vector<Decoded>&v,std::size_t idx,ZydisRegister start){
    auto cur=large(start);StackSlot slot{};bool have_slot=false;LocalStackTaint base;std::size_t seen=0;
    for(std::size_t z=idx;z-->0&&seen<32;){
        const auto&x=v[z];++seen;
        if(x.zi.meta.category==ZYDIS_CATEGORY_CALL||x.zi.meta.category==ZYDIS_CATEGORY_COND_BR||x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR)return{};
        if(have_slot){
            bool resolved=false;
            for(std::uint8_t oi=0;oi<x.zi.operand_count_visible;++oi){
                const auto&o=x.ops[oi];if(o.type!=ZYDIS_OPERAND_TYPE_MEMORY||(o.actions&ZYDIS_OPERAND_ACTION_WRITE)==0)continue;
                auto q=fixed_stack_slot(o,base);
                if(q){
                    if(!overlaps(*q,slot))continue;
                    if(q->base!=slot.base||q->offset!=slot.offset||q->width!=slot.width||oi!=0||x.zi.mnemonic!=ZYDIS_MNEMONIC_MOV||x.zi.operand_count_visible<2)return{};
                    const auto&src=x.ops[1];
                    if(src.type==ZYDIS_OPERAND_TYPE_IMMEDIATE&&!src.imm.is_relative)return static_cast<std::uint32_t>(src.imm.value.u);
                    if(src.type==ZYDIS_OPERAND_TYPE_REGISTER){cur=large(src.reg.value);have_slot=false;resolved=true;break;}
                    return{};
                }
                auto b=large(o.mem.base);if(b!=ZYDIS_REGISTER_RIP&&b!=ZYDIS_REGISTER_NONE)return{};
            }
            if(resolved)continue;
            if(have_slot){if((slot.base==StackBase::RSP&&writes_reg(x,ZYDIS_REGISTER_RSP))||(slot.base==StackBase::RBP&&writes_reg(x,ZYDIS_REGISTER_RBP)))return{};continue;}
        }
        if(!writes_reg(x,cur))continue;
        if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2&&x.ops[0].type==ZYDIS_OPERAND_TYPE_REGISTER){
            const auto&q=x.ops[1];
            if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE&&!q.imm.is_relative)return static_cast<std::uint32_t>(q.imm.value.u);
            if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){cur=large(q.reg.value);continue;}
            if(q.type==ZYDIS_OPERAND_TYPE_MEMORY){auto ss=fixed_stack_slot(q,base);if(!ss)return{};slot=*ss;have_slot=true;continue;}
        }
        if(x.zi.mnemonic==ZYDIS_MNEMONIC_XOR&&x.zi.operand_count_visible>=2&&x.ops[0].type==ZYDIS_OPERAND_TYPE_REGISTER&&x.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER&&large(x.ops[0].reg.value)==large(x.ops[1].reg.value))return 0;
        return{};
    }
    return{};
}
std::optional<std::uint64_t> leaf_before(const std::vector<Decoded>&v,std::size_t idx){return scalar_before(v,idx,ZYDIS_REGISTER_RAX);}
std::optional<std::uint64_t> subleaf_before(const std::vector<Decoded>&v,std::size_t idx){return scalar_before(v,idx,ZYDIS_REGISTER_RCX);}
bool selector_uses_sign(ZydisMnemonic m){return m==ZYDIS_MNEMONIC_JS||m==ZYDIS_MNEMONIC_JNS||m==ZYDIS_MNEMONIC_CMOVS||m==ZYDIS_MNEMONIC_CMOVNS;}
bool selector_uses_zero(ZydisMnemonic m){return m==ZYDIS_MNEMONIC_JZ||m==ZYDIS_MNEMONIC_JNZ||m==ZYDIS_MNEMONIC_CMOVZ||m==ZYDIS_MNEMONIC_CMOVNZ;}
std::optional<std::uint32_t> branch_target(const Decoded&x){if(x.zi.meta.category!=ZYDIS_CATEGORY_COND_BR||!x.zi.operand_count_visible)return{};const auto&o=x.ops[0];if(o.type!=ZYDIS_OPERAND_TYPE_IMMEDIATE||!o.imm.is_relative)return{};auto t=std::int64_t(x.rva+x.zi.length)+o.imm.value.s;if(t<0||t>0xffffffffll)return{};return static_cast<std::uint32_t>(t);}
bool return_selection(const std::vector<Decoded>&v,std::size_t idx,ZydisRegister dst){dst=large(dst);if(dst!=ZYDIS_REGISTER_RAX)return false;for(std::size_t i=idx+1;i<v.size()&&i<=idx+8;++i){const auto&x=v[i];if(x.zi.mnemonic==ZYDIS_MNEMONIC_RET)return true;if(writes_reg(x,dst))return false;if(x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR||x.zi.meta.category==ZYDIS_CATEGORY_COND_BR)return false;}return false;}
std::string known_predicate(std::uint64_t leaf,std::optional<std::uint64_t> subleaf,const Cond&c,ZydisMnemonic sel,std::optional<unsigned>&bit){bit.reset();if(leaf==1&&c.output=="ECX"){if(c.shape=="SELF_TEST"&&selector_uses_sign(sel)){bit=31;return"HYPERVISOR_PRESENT";}if((c.shape=="TEST_MASK"||c.shape=="AND_MASK")&&c.mask&&std::has_single_bit(c.mask)&&selector_uses_zero(sel)){bit=std::countr_zero(c.mask);if(*bit==31)return"HYPERVISOR_PRESENT";if(*bit==27)return"OSXSAVE";if(*bit==28)return"AVX";}}if(leaf==7&&subleaf&&*subleaf==0&&c.output=="EBX"&&(c.shape=="TEST_MASK"||c.shape=="AND_MASK")&&c.mask&&std::has_single_bit(c.mask)&&selector_uses_zero(sel)){bit=std::countr_zero(c.mask);if(*bit==5)return"AVX2";if(*bit==16)return"AVX512F";}return{};}
std::string known_xgetbv_predicate(std::optional<std::uint64_t>xcr,const Cond&c,ZydisMnemonic sel){if(!xcr||*xcr!=0||c.output!="EAX"||!c.inverted||c.shape!="TEST_MASK"||c.mask!=0x6||!selector_uses_zero(sel))return{};return"XCR0_XMM_YMM_ENABLED";}
bool is_timestamp(ZydisMnemonic m){return m==ZYDIS_MNEMONIC_RDTSC||m==ZYDIS_MNEMONIC_RDTSCP;}
std::string timestamp_name(ZydisMnemonic m){return m==ZYDIS_MNEMONIC_RDTSCP?"RDTSCP":"RDTSC";}
std::string timing_relation(ZydisMnemonic m){if(m==ZYDIS_MNEMONIC_JNB||m==ZYDIS_MNEMONIC_CMOVNB)return"UNSIGNED_GE";if(m==ZYDIS_MNEMONIC_JB||m==ZYDIS_MNEMONIC_CMOVB)return"UNSIGNED_LT";if(m==ZYDIS_MNEMONIC_JNBE||m==ZYDIS_MNEMONIC_CMOVNBE)return"UNSIGNED_GT";if(m==ZYDIS_MNEMONIC_JBE||m==ZYDIS_MNEMONIC_CMOVBE)return"UNSIGNED_LE";if(m==ZYDIS_MNEMONIC_JZ||m==ZYDIS_MNEMONIC_CMOVZ)return"EQ";if(m==ZYDIS_MNEMONIC_JNZ||m==ZYDIS_MNEMONIC_CMOVNZ)return"NE";return"CONDITIONAL";}
void add_range(Finding&f,const PeInfo&pe,std::span<const std::uint8_t>d,std::uint32_t rva,std::uint64_t size,std::string label){if(auto o=rvaoff(pe,rva,d.size()))f.ranges.push_back({*o,size,std::move(label)});}
Finding make_finding(std::span<const std::uint8_t>d,const PeInfo&pe,const PeRuntimeFunction&rf,const Decoded&cpuid,std::uint64_t leaf,std::optional<std::uint64_t> subleaf,const Cond&cond,const Decoded&sel,const std::vector<Decoded>&ins,std::size_t selidx){Finding f;f.kind="prerequisite";f.family="Execution prerequisite";std::optional<unsigned>bit;auto known=known_predicate(leaf,subleaf,cond,sel.zi.mnemonic,bit);f.variant=known.empty()?"CPUID-derived control gate":("CPUID "+known+" gate");f.state="CONFIRMED";f.confidence=known.empty()?0.92:0.98;f.fields["platform"]="windows";f.fields["architecture"]="x64";f.fields["source_instruction"]="CPUID";f.fields["cpuid_leaf"]=hx(leaf);if(subleaf)f.fields["cpuid_subleaf"]=hx(*subleaf);f.fields["cpuid_output"]=cond.output;f.fields["cpuid_rva"]=hx(cpuid.rva);f.fields["condition_rva"]=hx(cond.rva);f.fields["condition_shape"]=cond.shape;f.fields["selector_rva"]=hx(sel.rva);f.fields["selector_kind"]=sel.zi.meta.category==ZYDIS_CATEGORY_CMOV?"CMOV":"JCC";f.fields["selector_mnemonic"]=mnem(sel.zi.mnemonic);f.fields["function_rva"]=hx(rf.begin_rva);f.fields["control_dependency_state"]="CONFIRMED";f.fields["malicious_intent"]="NOT_INFERRED";if(cond.via_stack){f.fields["local_stack_taint"]="EXACT_SPILL_RELOAD";f.fields["stack_slot"]=cond.stack_slot;f.fields["stack_spill_rva"]=hx(cond.spill_rva);f.fields["stack_reload_rva"]=hx(cond.reload_rva);}if(cond.mask)f.fields["condition_mask"]=hx(cond.mask);if(cond.inverted)f.fields["condition_transform"]="BITWISE_NOT";if(cond.shape=="CMP_IMMEDIATE")f.fields["condition_immediate"]=hx(cond.imm);if(bit)f.fields["cpuid_bit"]=std::to_string(*bit);if(!known.empty())f.fields["predicate"]=known;if(sel.zi.meta.category==ZYDIS_CATEGORY_COND_BR){if(auto t=branch_target(sel))f.fields["branch_target_rva"]=hx(*t);f.fields["fallthrough_rva"]=hx(sel.rva+sel.zi.length);f.fields["gated_effect"]="CONTROL_FLOW_SELECTION";}else if(sel.zi.meta.category==ZYDIS_CATEGORY_CMOV&&sel.zi.operand_count_visible>=1&&sel.ops[0].type==ZYDIS_OPERAND_TYPE_REGISTER){f.fields["selector_destination"]=regname(sel.ops[0].reg.value);f.fields["gated_effect"]=return_selection(ins,selidx,sel.ops[0].reg.value)?"RETURN_VALUE_SELECTION":"CONDITIONAL_DATA_SELECTION";}
 f.evidence.push_back("a concrete CPUID output register remains data-dependent through a same-function condition and directly controls a conditional selector");if(cond.via_stack)f.evidence.push_back("the CPUID provenance crosses one exact fixed local stack-slot MOV spill/reload before the condition");if(!known.empty())f.evidence.push_back("CPUID leaf/output/condition geometry resolves the controlling predicate as "+known);if(sel.zi.meta.category==ZYDIS_CATEGORY_COND_BR)f.evidence.push_back("the CPUID-derived condition controls an explicit conditional branch with bounded target/fallthrough RVAs");else f.evidence.push_back("the CPUID-derived condition controls a conditional move rather than being inferred from instruction presence alone");f.negative_evidence.push_back("CPU/environment feature dispatch is common in benign software; software intent is not inferred");f.negative_evidence.push_back("the finding confirms a local execution prerequisite/control dependency, not the runtime value observed on this host");f.suggested_actions={"prioritize the selector target/fallthrough or selected return value before deeper reverse engineering","record the concrete runtime CPUID value only if later dynamic confirmation is needed"};add_range(f,pe,d,cpuid.rva,cpuid.zi.length,"CPUID prerequisite source");add_range(f,pe,d,cond.rva,1,"CPUID-derived condition");add_range(f,pe,d,sel.rva,sel.zi.length,"CPUID-derived conditional selector");return f;}
